//! Replays the pure rows of `tests/fixtures/keybindings.jsonl`, generated by
//! `tools/generate_keybinding_fixtures.mjs` from the original source.
use super::*;
use serde_json::json;

pub(crate) fn rows() -> Vec<Value> {
    include_str!("../tests/fixtures/keybindings.jsonl")
        .lines()
        .map(|line| serde_json::from_str(line).unwrap())
        .collect()
}
pub(crate) fn rows_of(kind: &str) -> Vec<Value> {
    rows().into_iter().filter(|row| row["type"] == kind).collect()
}

fn rule_of(value: &Value) -> Rule {
    Rule {
        key: value["key"].as_str().unwrap().into(),
        command: value["command"].as_str().unwrap().into(),
        when: value["when"].as_str().map(str::to_owned),
    }
}

#[test]
fn constants_and_defaults_match_the_original() {
    let constants = rows_of("constants").remove(0);
    let commands: Vec<&str> = constants["commands"].as_array().unwrap().iter().map(|c| c.as_str().unwrap()).collect();
    assert_eq!(commands, STATIC_KEYBINDING_COMMANDS);
    assert_eq!(constants["max"], MAX_KEYBINDINGS_COUNT);
    assert_eq!(constants["maxWhenDepth"], MAX_WHEN_EXPRESSION_DEPTH);
    let defaults: Vec<Rule> = constants["defaults"].as_array().unwrap().iter().map(rule_of).collect();
    assert_eq!(default_rules(), defaults);
    // The resolved defaults the original compiles, and the ones the contracts crate ships.
    let resolved = rows_of("defaults").remove(0);
    let ours: Vec<Value> = default_resolved().iter().map(Resolved::to_value).collect();
    assert_eq!(Value::Array(ours.clone()), resolved["resolved"]);
    assert_eq!(serde_json::to_value(t3_contracts::default_resolved_keybindings()).unwrap(), Value::Array(ours));
}

#[test]
fn shortcuts_parse_like_the_original() {
    let rows = rows_of("shortcut");
    assert!(rows.len() > 60);
    for row in rows {
        let input = row["input"].as_str().unwrap();
        let parsed = parse_shortcut(input).map(|shortcut| serde_json::to_value(shortcut).unwrap());
        assert_eq!(parsed.unwrap_or(Value::Null), row["shortcut"], "shortcut {input:?}");
    }
}

#[test]
fn when_expressions_parse_like_the_original() {
    let rows = rows_of("when");
    assert!(rows.len() > 60);
    for row in rows {
        let input = row["input"].as_str().unwrap();
        let parsed = parse_when(input).map(|node| serde_json::to_value(node).unwrap());
        assert_eq!(parsed.unwrap_or(Value::Null), row["ast"], "when {input:?}");
    }
}

#[test]
fn rules_compile_and_encode_like_the_original() {
    for row in rows_of("compile") {
        let rule = rule_of(&row["rule"]);
        let resolved = compile_rule(&rule);
        assert_eq!(resolved.as_ref().map(Resolved::to_value).unwrap_or(Value::Null), row["resolved"], "{rule:?}");
        if let Some(resolved) = resolved {
            let key = encode_shortcut(&resolved.shortcut).unwrap();
            let when = resolved.when_ast.as_ref().map(encode_when);
            let mut encoded = json!({"key":key,"command":resolved.command});
            if let Some(when) = when {
                encoded["when"] = json!(when);
            }
            assert_eq!(encoded, row["encoded"], "{rule:?}");
        }
    }
}

#[test]
fn encoding_is_the_inverse_for_shortcuts_with_a_spelling() {
    assert_eq!(encode_shortcut(&parse_shortcut("mod++").unwrap()).as_deref(), Some("mod++"));
    assert_eq!(encode_shortcut(&parse_shortcut("shift+space").unwrap()).as_deref(), Some("shift+space"));
    assert_eq!(encode_shortcut(&Shortcut { key: "a+b".into(), meta_key: false, ctrl_key: false, shift_key: false, alt_key: false, mod_key: false }), None);
    assert_eq!(encode_shortcut(&Shortcut { key: String::new(), meta_key: false, ctrl_key: false, shift_key: false, alt_key: false, mod_key: false }), None);
}

#[test]
fn merging_keeps_the_last_256_and_overrides_by_command() {
    let custom = compile_config(&(0..300).map(|i| Rule { key: "mod+alt+f1".into(), command: format!("script.s{i}.run"), when: None }).collect::<Vec<_>>());
    assert_eq!(custom.len(), 256);
    assert_eq!(custom[0].command, "script.s44.run");
    let merged = merge_with_defaults(custom);
    assert_eq!(merged.len(), 256);
    assert_eq!(merged.last().unwrap().command, "script.s299.run");
    let override_toggle = merge_with_defaults(vec![compile_rule(&Rule { key: "mod+shift+y".into(), command: "terminal.toggle".into(), when: None }).unwrap()]);
    assert_eq!(override_toggle.iter().filter(|rule| rule.command == "terminal.toggle").count(), 1);
    assert_eq!(override_toggle.last().unwrap().shortcut.key, "y");
    assert_eq!(merge_with_defaults(Vec::new()).len(), default_resolved().len());
}
